import re, glob, subprocess

libs = {f: open(f).read() for f in glob.glob('library/*.md')}
def norm(s):
    s = s.replace('\u2019',"'").replace('\u2018',"'").replace('\u201c','"').replace('\u201d','"')
    return re.sub(r'\s+',' ',s)
libn = {f: norm(t) for f,t in libs.items()}

print('=== quotes in deliverables not found verbatim in library ===')
seen=set()
for f in ['deliverable/return.md','deliverable/judgment_calls.md','deliverable/STATUS.md','deliverable/QUESTIONS.md']:
    txt = norm(open(f).read())
    for m in re.finditer(r'"([^"]{12,})"', txt):
        q = m.group(1).strip()
        if any(q in t for t in libn.values()):
            continue
        key=(f,q)
        if key in seen: continue
        seen.add(key)
        print(f' * {f}: {q[:100]}')

print()
print('=== stale sensitivity figures ===')
for pat in ['2,805.57','1,416','906','6,044.34','3,855.66','7,094.43','217.49']:
    r = subprocess.run(['grep','-rn',pat,'deliverable/'],capture_output=True,text=True)
    if r.stdout.strip():
        print(pat, '->')
        print(r.stdout.strip()[:400])
print('done')
